:where(.ds-settings-window) button { display: inline-flex; align-items: center; justify-content: center; gap: 7px; cursor: default; border: 0; background: transparent; border-radius: var(--radius-control, 7px); padding: 0; color: inherit; font: inherit; flex-shrink: 0; } :where(.ds-settings-window) button:hover:not(:disabled) { background: var(--hover, #e3e0e7); } :where(.ds-settings-window) button:focus-visible { outline: 2px solid var(--accent, #714a9e); outline-offset: 2px; } :where(.ds-settings-window) button:disabled { opacity: .38; }
.ds-settings-window {
	display: flex;
	flex-direction: column;
	height: 100%;
	background: var(--bg, #faf9f7);
}
.ds-settings-toolbar {
	flex-shrink: 0;
	background: var(--chrome, #eeedeb);
	border-bottom: 1px solid var(--border, #dcd9df);
}
.ds-settings-window-title {
	display: flex;
	align-items: center;
	justify-content: center;
	height: 36px;
	font-size: 13px;
	font-weight: 600;
	user-select: none;
}
.ds-settings-tabs {
	display: flex;
	justify-content: center;
	gap: 8px;
	padding: 0 20px 10px;
}
.ds-settings-tabs > button {
	flex-direction: column;
	gap: 4px;
	width: 68px;
	height: 61px;
	color: var(--text-muted, #655e6d);
	font-size: 11px;
	border-radius: 8px;
}
.ds-settings-tabs > button[aria-selected='true'] {
	color: var(--accent, #714a9e);
	background: color-mix(in srgb, var(--text, #29262e) 7%, transparent);
	box-shadow: inset 0 1px color-mix(in srgb, var(--text, #29262e) 8%, transparent);
}
.ds-settings-content {
	flex: 1;
	min-height: 0;
	overflow-y: auto;
	padding: 26px 32px 24px;
}
.ds-preference-row {
	display: grid;
	grid-template-columns: 100px minmax(0, 1fr);
	align-items: center;
	gap: 12px;
	font-size: 12px;
}
.ds-preference-label {
	text-align: right;
	font-weight: 600;
}
.ds-appearance-row {
	align-items: start;
}
.ds-appearance-row .ds-preference-label {
	padding-top: 12px;
}
.ds-appearance-options {
	display: flex;
	gap: 14px;
}
.ds-appearance-choice {
	flex: 1;
	min-width: 0;
	flex-direction: column;
	gap: 6px;
	padding: 3px;
	font-size: 11px;
}
.ds-appearance-choice > span:last-child {
	display: inline-flex;
	align-items: center;
	gap: 4px;
}
.ds-appearance-choice:hover:not(:disabled) {
	background: transparent;
}
.ds-appearance-choice:hover .ds-theme-preview {
	border-color: var(--accent, #714a9e);
}
.ds-theme-preview {
	width: 100%;
	height: 54px;
	border-radius: 7px;
	background: #f5f3f7;
	position: relative;
	border: 1px solid #c7c1cd;
	margin-bottom: 4px;
}
.ds-theme-preview::before {
	content: '';
	position: absolute;
	inset: 13px 5px 4px 28px;
	background: #fff;
	border-radius: 2px;
}
.ds-theme-preview::after {
	content: '';
	position: absolute;
	top: 6px;
	left: 6px;
	width: 4px;
	height: 4px;
	border-radius: 50%;
	background: #b8a2cf;
	box-shadow:
		7px 0 #a6a0b1,
		14px 0 #c8c3cf;
}
.ds-appearance-choice.ds-dark .ds-theme-preview {
	background: #343139;
	border-color: #56505f;
}
.ds-appearance-choice.ds-dark .ds-theme-preview::before {
	background: #242427;
}
.ds-appearance-choice.ds-system .ds-theme-preview {
	background: linear-gradient(110deg, #f5f3f7 50%, #343139 50%);
}
.ds-appearance-choice.ds-system .ds-theme-preview::before {
	background: linear-gradient(110deg, #fff 50%, #242427 50%);
}
.ds-appearance-choice.ds-selected .ds-theme-preview {
	outline: 2px solid var(--accent, #714a9e);
	outline-offset: 2px;
}
.ds-appearance-choice.ds-selected {
	color: var(--accent, #714a9e);
}
.ds-settings-font-preview {
	margin: 20px 0 0 112px;
	padding: 12px 16px;
	border-radius: 7px;
	background: var(--surface, #f3f2f0);
	color: var(--text, #29262e);
	font-family: var(--font-mono, 'SFMono-Regular', Menlo, Consolas, monospace);
	line-height: 1.8;
	overflow: auto;
}
.ds-settings-font-preview code {
	font: inherit;
}
.ds-settings-font-preview code > span {
	color: var(--syntax-keyword, #964c91);
}
.ds-settings-error {
	margin: 16px 0 0;
	color: var(--danger, #ac3043);
	font-size: 11px;
}

.ds-settings-window { width: 568px; height: 348px; color: var(--text, #29262e); font: 12px/1.5 var(--font-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif); } .ds-settings-window .ds-subtle-button { background: var(--raised, #fff); padding: 5px 10px; box-shadow: var(--shadow-control, 0 1px 2px #24192d0c); }

