.ds-combobox-trigger {
	width: 90px;
	height: 28px;
	padding: 0 9px;
	justify-content: space-between;
	background: var(--raised, #ffffff);
	border: 1px solid var(--border-input, #857d8c);
	font-weight: 400;
}
.ds-combobox-trigger > span {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.ds-combobox-trigger > svg {
	width: 13px;
	height: 13px;
	color: var(--text-muted, #655e6d);
}

:where(.ds-update-surface) button { display: inline-flex; align-items: center; justify-content: center; gap: 7px; cursor: default; border: 0; background: transparent; border-radius: var(--radius-control, 7px); padding: 0; color: inherit; font: inherit; flex-shrink: 0; } :where(.ds-update-surface) button:hover:not(:disabled) { background: var(--hover, #e3e0e7); } :where(.ds-update-surface) button:focus-visible { outline: 2px solid var(--accent, #714a9e); outline-offset: 2px; } :where(.ds-update-surface) button:disabled { opacity: .38; }
.ds-update-surface { --text: #f1edf7; --text-muted: #c1b8cd; --bg: #17171c; --chrome: #27242d; --surface: #232129; --raised: #38303f; --border: #3b3544; --accent: #e1baf7; --accent-soft: #543961; --hover: #3b3047; display: flex; flex-direction: column; width: 784px; height: 564px; background: var(--bg); color: var(--text); font: 12px/1.5 var(--font-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif); color-scheme: dark; } .ds-update-titlebar { display: flex; align-items: center; gap: 10px; flex-shrink: 0; height: 52px; padding: 0 16px 0 20px; } .ds-update-titlebar > strong { flex: 1; font-size: 15px; font-weight: 600; letter-spacing: -.3px; } .ds-update-surface .ds-icon-button { width: 30px; height: 28px; border-radius: 6px; color: var(--text-muted); }
.ds-update-controls {
	display: flex;
	align-items: center;
	gap: 8px;
	-webkit-app-region: no-drag;
}
.ds-update-check-button {
	min-height: 29px;
	padding: 0 14px;
	background: color-mix(in srgb, var(--text, #29262e) 8%, var(--bg, #faf9f7));
	box-shadow: var(--shadow-control, 0 1px 2px #24192d0c);
	border-radius: 16px;
	font-size: 11px;
	font-weight: 500;
}
.ds-updates-page {
	flex: 1;
	min-height: 0;
	overflow-y: auto;
}
.ds-update-status {
	padding: 10px 24px;
	border-bottom: 1px solid var(--border, #dcd9df);
	color: var(--text-muted, #655e6d);
	font-size: 11px;
}
.ds-update-status.ds-error {
	color: var(--danger, #ac3043);
}
.ds-update-progress {
	display: block;
	width: calc(100% - 48px);
	height: 4px;
	margin: 10px 24px 0;
	accent-color: var(--accent, #714a9e);
}
.ds-release-history {
	padding: 22px 24px 32px;
	max-width: 800px;
}
.ds-release-heading {
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: 12px;
	margin-bottom: 22px;
}
.ds-release-heading h1 {
	font-size: 27px;
	font-weight: 650;
	letter-spacing: -0.6px;
	line-height: 1.25;
	margin: 0;
}
.ds-release-heading h1 span {
	font-weight: 400;
	font-variant-numeric: tabular-nums;
}
.ds-release-current {
	color: var(--accent, #714a9e);
	background: var(--accent-soft, #e4d9ef);
	padding: 2px 7px;
	border-radius: 4px;
	font-size: 10px;
}
.ds-release-notes + .ds-release-notes {
	border-top: 1px solid var(--border, #dcd9df);
	padding-top: 28px;
	margin-top: 30px;
}
.ds-release-notes h2 {
	font-size: 12px;
	font-weight: 600;
	color: var(--accent, #714a9e);
	margin: 24px 0 10px;
}
.ds-release-notes p,
.ds-release-notes li {
	font-size: 12px;
	line-height: 1.85;
	overflow-wrap: anywhere;
}
.ds-release-notes p {
	margin: 12px 0;
	color: var(--text-muted, #655e6d);
}
.ds-release-notes ul {
	padding-left: 20px;
	margin: 10px 0 20px;
}
.ds-release-notes li + li {
	margin-top: 8px;
}
.ds-release-notes strong {
	color: var(--text, #29262e);
	font-weight: 600;
}
.ds-release-notes code {
	font-family: var(--font-mono, 'SFMono-Regular', Menlo, Consolas, monospace);
	font-size: 0.95em;
	background: var(--surface, #f3f2f0);
	border-radius: 3px;
	padding: 1px 4px;
}
